class SecurityGroup {
    private final Map<Integer, String> inboundAllows = new HashMap<>();
    void allowInbound(int port, String cidr) { inboundAllows.put(port, cidr); }
    boolean inboundAllowed(int port, String sourceIp) {
        String cidr = inboundAllows.get(port);
        return cidr != null && sourceIp.startsWith(cidr.split("/")[0].substring(0, 4));
    }
    boolean returnAllowed() { return true; }  // stateful: responses always allowed
}

// ─── Would be in AclRule.java ───
class AclRule {
    final int number; final String action; final int port; final String cidr;
    AclRule(int number, String action, int port, String cidr) {
            this.number = number;
            this.action = action
            this.port = port
            this.cidr = cidr;
    }
    boolean matches(int p, String ip) {
        boolean portOk = port == 0 || port == p;
        boolean ipOk = ip.startsWith(cidr.split("/")[0].substring(0, 4));
        return portOk && ipOk;
    }
}

// ─── Would be in NetworkAcl.java ───
class NetworkAcl {
    private final List<AclRule> inbound = new ArrayList<>();
    void addInbound(AclRule r) {
        inbound.add(r);
        inbound.sort(Comparator.comparingInt(x -> x.number)); // lowest number first
    }
    String evaluateInbound(int port, String ip) {
        for (AclRule r : inbound) {                 // stop at first match
            if (r.matches(port, ip)) return r.action.toUpperCase();
        }
        return "DENY (implicit default)";
    }
}

